/* ============================================================================
   PANEL-01 · Mi Panel — estilos del panel de contenido.
   Los colores salen todos de los tokens del sistema. Dos sustituciones
   respecto al HTML aprobado, explicadas también en la cabecera del TSX:
   el blanco de tarjeta (no hay token) y la sombra de hover (no hay token).
   ========================================================================== */

.body {
  flex: 1;
  overflow-y: auto;
  min-width: 0;
  padding: 24px 28px 40px;
  background: var(--bw-cold-white);
}

.inner {
  max-width: 820px;
}

/* Los tamaños de fuente siguen el HTML aprobado de PANEL-01; los tokens
   --bw-size-* del sistema no mapean a esta pantalla (p. ej. el eyebrow de
   contenido es 10px, no el --bw-size-eyebrow de 14px). */
.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-calibration-blue);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin-bottom: 3px;
}

.sub {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  margin-bottom: 24px;
  max-width: 600px;
}

/* ── Rejilla (spec §4) ──────────────────────────────────────────────────── */
.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

@media (max-width: 720px) {
  .grid {
    grid-template-columns: 1fr;
  }
}

/* ── Tarjeta ────────────────────────────────────────────────────────────── */
.card {
  /* Reset de botón: la tarjeta es un <button> de verdad (RNG-PANEL-03). */
  appearance: none;
  -webkit-appearance: none;
  width: 100%;
  font-family: var(--bw-font-body);
  text-align: left;
  /* El HTML aprobado usa blanco puro (#FFFFFF); el sistema no expone blanco,
     así que se usa el neutro más cercano: Warm Cream #FAF8F4. Sobre Cold
     White contrasta igual que el blanco. */
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 10px;
  padding: 18px 20px;
  cursor: pointer;
  color: var(--bw-deep-steel);
  display: flex;
  flex-direction: column;
  gap: 6px;
  transition: transform 0.15s ease, border-color 0.15s ease;
}

/* El hover del HTML aprobado usa una sombra rgba que no tiene token en el
   sistema; en su lugar se eleva la tarjeta físicamente (spec §4: "leve
   elevación") y se refuerza el borde con Line Steel Strong. */
.card:hover:not(:disabled) {
  border-color: var(--bw-line-steel-strong);
  transform: translateY(-1px);
}

.card:disabled {
  cursor: not-allowed;
}

.wide {
  grid-column: 1 / -1;
}

.cardHd {
  display: flex;
  align-items: center;
  gap: 9px;
}

.cardIco {
  width: 32px;
  height: 32px;
  border-radius: 7px;
  background: var(--bw-icon-tint-blue);
  color: var(--bw-calibration-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
  flex-shrink: 0;
}

.cardTitle {
  font-family: var(--bw-font-title);
  font-size: 13px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.cardNum {
  font-family: var(--bw-font-title);
  font-size: 32px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  line-height: 1;
}

.cardLabel {
  font-size: 12px;
  color: var(--bw-steel-mist);
}

.cardLine {
  font-size: 13px;
  color: var(--bw-ink-steel);
}

.cardLine b {
  color: var(--bw-deep-steel);
  font-weight: 600;
}

/* ── Resumen mes (spec §4.5) ────────────────────────────────────────────── */
.metricsRow {
  display: flex;
  gap: 32px;
}

.metric {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

@media (max-width: 520px) {
  .metricsRow {
    flex-direction: column;
    gap: 14px;
  }
}

/* ── Error de carga ─────────────────────────────────────────────────────── */
.error {
  margin-bottom: 16px;
  padding: 12px 14px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  background: var(--bw-sensitive-bg);
  color: var(--bw-error-text);
  font-size: 14px;
  line-height: 1.5;
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

