import { useEffect, useState, type ReactNode } from 'react';
import { errorMessage, type MemberProfile } from '../../lib/session';
import {
  dateLabel,
  fetchPanelSummary,
  latestOfferLine,
  latestQueryLine,
  metricLabel,
  subtitleLabel,
  type PanelSummary,
} from '../../lib/panel';
import styles from './Panel.module.css';

/**
 * PANEL-01 · Mi Panel (dashboard de entrada tras login).
 * Contrato: `openspec/design-gui/specs y html aprobados/specs/Rinworld_spec_PANEL-01.md`
 * y su HTML aprobado.
 *
 * =============================================================================
 * CINCO DECISIONES QUE LA SPEC NO PODÍA TOMAR
 * =============================================================================
 *
 * 1 · TRES MÉTRICAS SE PINTAN CON GUIÓN, NUNCA CON CERO.
 *    `fetchPanelSummary` (entregada, F-057) devuelve `null` —no `0`— para
 *    visitas de inventario, hilos sin leer y favoritos del mes: no hay tabla de
 *    visitas, no hay registro de lectura y la RLS de favoritos devolvería 0 en
 *    silencio. RNG-PANEL-02 pide cajas visibles "incluso en valor 0", pero un 0
 *    afirmaría que se ha mirado y no había nada; el guion (`metricLabel(null)`)
 *    dice que esto todavía no se mide. Ver la cabecera de `app/src/lib/panel.ts`.
 *
 * 2 · "FAVORITOS RECIBIDOS" NO NAVEGA A NINGUNA PARTE.
 *    La spec §4.6 la manda a DIR-01/DIR-02, y esas pantallas no existen en el
 *    MVP. La tarjeta sigue siendo un `<button>` (RNG-PANEL-03) pero va
 *    `disabled`, con la razón en `title` + `aria-describedby` — el mismo patrón
 *    que el botón de subida de INV-01. Una tarjeta que "navega" a una pantalla
 *    que no existe es el riesgo #1 de `CLAUDE.md` §7 llevado a la interfaz.
 *
 * 3 · LA CAJA DE HILOS NO TIENE LÍNEA DE DETALLE CON DATOS.
 *    El HTML aprobado muestra "Más reciente: NSK Europe Ltd — con oferta
 *    pendiente" pero `fetchPanelSummary` devuelve `threads.latest: null` porque
 *    no hay registro de lectura (F-027 a). Pintar ese texto del mock sería
 *    inventar un dato: la tarjeta muestra el número con guion y la línea
 *    "Sin hilos con mensajes sin leer", el mismo patrón que las cajas de
 *    ofertas y consultas usan con `latestOfferLine`/`latestQueryLine`.
 *
 * 4 · EL BLANCO DE LAS TARJETAS NO ES UN TOKEN.
 *    El sistema no expone blanco puro (`#FFFFFF` no está en la paleta), así que
 *    las tarjetas usan `--bw-warm-cream`, el neutro más cercano. Sobre Cold
 *    White el contraste es el mismo. Ver el CSS.
 *
 * 5 · EL HOVER ELEVA SIN SOMBRA.
 *    El hover del HTML aprobado usa `box-shadow: 0 4px 14px rgba(...)` y el
 *    sistema no tiene token de sombra de tarjeta. En vez de un rgba suelto
 *    (prohibido), la spec §4 pide "leve elevación" y eso se hace con
 *    `translateY(-1px)` + borde `--bw-line-steel-strong`.
 */

const EYEBROW = 'Panel · PANEL-01';
const TITLE = 'Mi Panel';

const FAVORITES_WHY =
  'El perfil de empresa (DIR-01/DIR-02) está fuera del alcance del MVP: esta tarjeta no navega a ninguna parte.';
const THREADS_EMPTY_LINE = 'Sin hilos con mensajes sin leer';

type Screen = 'Vendiendo' | 'Comprando' | 'Inventario' | 'Hilos';

interface Props {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  onNavigate: (screen: Screen) => void;
}

export function Panel({ profile, now, onNavigate }: Props) {
  const [summary, setSummary] = useState<PanelSummary | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const orgId = profile.orgId;
  // Normalizar `now` a timestamp: si el padre crea un `Date` nuevo con la misma
  // fecha, la identidad cambia pero el valor no; el efecto no debe relanzarse.
  const nowMs = now?.getTime();

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    setSummary(null);

    const panelNow = nowMs !== undefined ? new Date(nowMs) : undefined;

    fetchPanelSummary(panelNow ? { orgId, now: panelNow } : { orgId })
      .then((s) => {
        if (!cancelled) setSummary(s);
      })
      .catch((e) => {
        if (!cancelled) setError(`No se ha podido cargar el panel. ${errorMessage(e)}`);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [orgId, nowMs]);

  return (
    <div className={styles.body}>
      <div className={styles.inner}>
        <div className={styles.eyebrow}>{EYEBROW}</div>
        <h1 className={styles.title}>{TITLE}</h1>
        <p className={styles.sub}>{subtitleLabel(profile.fullName, profile.email, now)}</p>

        {error !== null && (
          <div className={styles.error} role="alert">
            {error}
          </div>
        )}

        {summary !== null && !loading && (
          <div className={styles.grid}>
            {/* ── 4.1 · Ofertas ──────────────────────────────────────────── */}
            <Card
              icon="ti ti-tag"
              title="Ofertas"
              testId="panel-offers"
              onClick={() => onNavigate('Vendiendo')}
            >
              <div className={styles.cardNum}>{metricLabel(summary.offers.pending)}</div>
              <div className={styles.cardLabel}>pendientes de respuesta</div>
              <div className={styles.cardLine}>{latestOfferLine(summary.offers.latest)}</div>
            </Card>

            {/* ── 4.2 · Consultas ────────────────────────────────────────── */}
            <Card
              icon="ti ti-search"
              title="Consultas"
              testId="panel-queries"
              onClick={() => onNavigate('Comprando')}
            >
              <div className={styles.cardNum}>{metricLabel(summary.queries.unanswered)}</div>
              <div className={styles.cardLabel}>sin respuesta</div>
              <div className={styles.cardLine}>{latestQueryLine(summary.queries.latest)}</div>
            </Card>

            {/* ── 4.3 · Inventario ───────────────────────────────────────── */}
            <Card
              icon="ti ti-package"
              title="Inventario"
              testId="panel-inventory"
              onClick={() => onNavigate('Inventario')}
            >
              <div className={styles.cardLine}>
                <b>{summary.inventory.published.toLocaleString('es-ES')}</b> líneas publicadas
              </div>
              <div className={styles.cardLine}>
                Última publicación: {dateLabel(summary.inventory.lastUploadAt)}
              </div>
              <div className={styles.cardLine}>
                <b>{metricLabel(summary.inventory.visits)}</b> visitas (30d)
              </div>
            </Card>

            {/* ── 4.4 · Hilos ────────────────────────────────────────────── */}
            <Card
              icon="ti ti-messages"
              title="Hilos"
              testId="panel-threads"
              onClick={() => onNavigate('Hilos')}
            >
              <div className={styles.cardNum}>{metricLabel(summary.threads.unread)}</div>
              <div className={styles.cardLabel}>con mensajes sin leer</div>
              {/* `latest` es siempre `null` (F-027 a): no hay registro de
                  lectura. Ver decisión 3 en la cabecera. */}
              <div className={styles.cardLine}>{THREADS_EMPTY_LINE}</div>
            </Card>

            {/* ── 4.5 · Resumen mes (ancho completo) ─────────────────────── */}
            <Card
              icon="ti ti-circle-check"
              title="Resumen mes"
              testId="panel-month"
              wide
              onClick={() => onNavigate('Vendiendo')}
            >
              <div className={styles.metricsRow}>
                <Metric
                  value={metricLabel(summary.month.acceptedOffers)}
                  label="Ofertas Aceptadas"
                  testId="metric-accepted-offers"
                />
                <Metric
                  value={metricLabel(summary.month.madeOffers)}
                  label="Ofertas Realizadas"
                  testId="metric-made-offers"
                />
                <Metric
                  value={metricLabel(summary.month.receivedQueries)}
                  label="Consultas Realizadas"
                  testId="metric-received-queries"
                />
              </div>
            </Card>

            {/* ── 4.6 · Favoritos recibidos — no navega (DIR fuera del MVP) ─ */}
            <Card
              icon="ti ti-star"
              title="Favoritos recibidos"
              testId="panel-favorites"
              disabled
              why={FAVORITES_WHY}
              describedBy="favorites-why"
            >
              <div className={styles.cardNum}>{metricLabel(summary.favorites.monthly)}</div>
              <div className={styles.cardLabel}>
                organizaciones te añadieron a favoritos este mes
              </div>
            </Card>
          </div>
        )}

        <span id="favorites-why" className={styles.srOnly}>
          {FAVORITES_WHY}
        </span>
      </div>
    </div>
  );
}

interface CardProps {
  icon: string;
  title: string;
  testId: string;
  onClick?: () => void;
  disabled?: boolean;
  wide?: boolean;
  /** Razón por la que la tarjeta está deshabilitada; sale en `title` y sr-only. */
  why?: string;
  describedBy?: string;
  children: ReactNode;
}

function Card({ icon, title, testId, onClick, disabled, wide, why, describedBy, children }: CardProps) {
  return (
    <button
      type="button"
      className={`${styles.card} ${wide ? styles.wide : ''}`}
      data-testid={testId}
      onClick={onClick}
      disabled={disabled}
      title={why}
      {...(describedBy !== undefined ? { 'aria-describedby': describedBy } : {})}
    >
      <div className={styles.cardHd}>
        <div className={styles.cardIco}>
          <i className={icon} aria-hidden="true" />
        </div>
        <div className={styles.cardTitle}>{title}</div>
      </div>
      {children}
    </button>
  );
}

interface MetricProps {
  value: string;
  label: string;
  testId: string;
}

function Metric({ value, label, testId }: MetricProps) {
  return (
    <div className={styles.metric} data-testid={testId}>
      <div className={styles.cardNum}>{value}</div>
      <div className={styles.cardLabel}>{label}</div>
    </div>
  );
}

